let paused=false,elapsed=0,mode='day',last=performance.now();const env={bg:new THREE.Color('#eef0e7'),sun:new THREE.Color('#fff4d1'),hemi:new THREE.Color('#f4f2d6'),sunPower:3.2,ambient:2.5,exposure:1.25};const target={...env,bg:env.bg.clone(),sun:env.sun.clone(),hemi:env.hemi.clone()};
const modes={day:{bg:'#eef0e7',sun:'#fff4d1',hemi:'#f4f2d6',sunPower:3.2,ambient:2.5,exposure:1.25,label:'晴朗的午后',note:'微风 · 适合发呆',icon:'☀'},sunset:{bg:'#ede0cc',sun:'#ffbd72',hemi:'#f0cfaf',sunPower:3.4,ambient:1.7,exposure:1.15,label:'温柔的日落',note:'晚霞 · 炊烟袅袅',icon:'◒'},night:{bg:'#293f46',sun:'#9fb6dd',hemi:'#a9bcd0',sunPower:.8,ambient:1.15,exposure:1,label:'安静的星夜',note:'星光 · 好梦将至',icon:'☾'}};
function setMode(v){mode=v;const e=modes[v];target.bg.set(e.bg);target.sun.set(e.sun);target.hemi.set(e.hemi);for(const k of ['sunPower','ambient','exposure'])target[k]=e[k];document.body.classList.toggle('night',v==='night');document.querySelector('#weather-label').textContent=e.label;document.querySelector('#weather-note').textContent=e.note;document.querySelector('#weather-icon').textContent=e.icon;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===v));moon.visible=v==='night';toast(v==='night'?'小镇亮起了暖灯':v==='sunset'?'留一会儿，看看晚霞':'阳光回到了山谷')}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
let toastTimer;function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.opacity=0,2600)}
document.querySelector('#rotate').onclick=()=>{controls.autoRotate=!controls.autoRotate;document.querySelector('#rotate').classList.toggle('on',controls.autoRotate);toast(controls.autoRotate?'开始环绕山谷':'已停止自动环绕')};
document.querySelector('#pause').onclick=()=>{paused=!paused;const b=document.querySelector('#pause');b.textContent=paused?'▷':'Ⅱ';b.setAttribute('aria-label',paused?'继续动画':'暂停动画');b.classList.toggle('on',paused);document.querySelector('#activity').textContent=paused?'时间在这里停了一会儿':'山谷里的日常正在继续'};
document.querySelector('#reset').onclick=()=>{camera.position.copy(mobile()?new THREE.Vector3(40,34,47):homePos);controls.target.set(0,2,0);controls.autoRotate=false;document.querySelector('#rotate').classList.remove('on');controls.update();toast('回到最初的风景')};
document.querySelector('#capture').onclick=()=>{renderer.render(scene,camera);const save=url=>{const a=document.createElement('a');a.download='山间牧歌-'+mode+'.png';a.href=url;a.click();toast('风景已保存')};if(!fallback){save(renderer.domElement.toDataURL('image/png'));return}const source=new XMLSerializer().serializeToString(renderer.domElement),url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml;charset=utf-8'})),im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=innerWidth;c.height=innerHeight;c.getContext('2d').drawImage(im,0,0);URL.revokeObjectURL(url);save(c.toDataURL('image/png'))};im.src=url};
const info=document.querySelector('#info');document.querySelector('#about').onclick=()=>info.showModal();document.querySelector('#close-info').onclick=()=>info.close();document.querySelector('#enter').onclick=()=>info.close();info.onclick=e=>{if(e.target===info)info.close()};
