for(const a of animals){const xx=a.base.x+Math.sin(t*a.speed*.2+a.phase)*.55,zz=a.base.z+Math.cos(t*a.speed*.2+a.phase)*.42;a.g.position.set(xx,height(xx,zz)+Math.max(0,Math.sin((t-(a.g.userData.greet??-10))*7))*(t-(a.g.userData.greet??-10)<1?.12:0),zz);a.head.rotation.z=-.15+Math.sin(t*.7+a.phase)*.2;const walking=Math.sin(t*.25+a.phase)>.6;for(let j=0;j<a.legs.length;j++)a.legs[j].rotation.z=walking?Math.sin(t*3+j*Math.PI)*.16:0;}
